import{anyOf,codeIs,messageMatches,nameIs}from"../rule.js";const MODEL_PROVIDER_RULES=[{id:`model-provider-api-key-missing`,name:`Model provider API key missing`,tags:[`model-provider`,`config`],when:anyOf(nameIs(`LoadAPIKeyError`,`AI_LoadAPIKeyError`),messageMatches(/API key is missing/i)),message:`The model provider could not load an API key.`,hint:"Export the provider's API key environment variable (for example `AI_GATEWAY_API_KEY` or `OPENAI_API_KEY`) and try again."},{id:`empty-model-response`,name:`Empty model response`,tags:[`model-provider`,`transient`],when:nameIs(`EmptyModelResponseError`),message:e=>e.message},{id:`model-response-content-filtered`,name:`Model response filtered`,tags:[`model-provider`,`recoverable`,`refused`],when:nameIs(`ContentFilteredModelResponseError`),message:`The model provider filtered this response.`,hint:`Review the request and its context against your model provider's content policy.`},{id:`model-request-cyber-policy-refused`,name:`Model request refused`,tags:[`model-provider`,`recoverable`,`refused`],when:codeIs(`cyber_policy`),message:`The model provider refused this request for possible cybersecurity risk.`,hint:`Review the request against your model provider's usage policies.`},{id:`model-request-bio-policy-refused`,name:`Model request refused`,tags:[`model-provider`,`recoverable`,`refused`],when:codeIs(`bio_policy`),message:`The model provider refused this request for possible biological risk.`,hint:`Review the request against your model provider's usage policies.`},{id:`model-capability-unsupported`,name:`Model capability not supported`,tags:[`model-provider`],when:nameIs(`AI_UnsupportedFunctionalityError`),message:`The selected model does not support a capability this agent uses (a tool type, modality, or feature).`,hint:`Remove the unsupported tool or switch to a model that supports it.`}];export{MODEL_PROVIDER_RULES};